import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';

/** `{ en_to_de: { [glossaryId]: label } }` */

/**
 * Keyed by the settings page instance, so the glossaries are fetched once per
 * visit and survive the component remounting when the driver select changes.
 */
const loads = new WeakMap();

/**
 * One glossary select per language pair, loaded from the DeepL account on first display.
 */
export default class DeeplGlossarySettings extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    if (!loads.has(this.attrs.page)) this.load();
  }
  glossaryLoad() {
    return loads.get(this.attrs.page) ?? {
      loading: false,
      failed: false,
      pairs: null
    };
  }
  load() {
    if (this.glossaryLoad().loading) return;
    const state = {
      ...this.glossaryLoad(),
      loading: true,
      failed: false
    };
    loads.set(this.attrs.page, state);
    app.request({
      method: 'GET',
      url: `${app.forum.attribute('apiUrl')}/fof-translate/deepl/glossaries`
    }).then(response => {
      state.pairs = response?.data && typeof response.data === 'object' ? response.data : {};
    }).catch(() => {
      state.failed = true;
    }).finally(() => {
      state.loading = false;
      m.redraw();
    });
  }
  view() {
    return m("div", {
      className: "Form-group FofTranslateDeeplGlossaries"
    }, m("label", null, app.translator.trans('fof-translate.admin.settings.deepl.glossaries_heading')), m("p", {
      className: "helpText"
    }, app.translator.trans('fof-translate.admin.settings.deepl.glossaries_help'), ' ', !this.glossaryLoad().loading && !this.glossaryLoad().failed && m(Button, {
      className: "Button Button--link FofTranslateDeeplGlossaries-reload",
      icon: "fas fa-sync",
      onclick: () => this.load()
    }, app.translator.trans('fof-translate.admin.settings.deepl.glossaries_reload_button'))), this.content());
  }
  content() {
    const {
      loading,
      failed,
      pairs: loaded
    } = this.glossaryLoad();
    if (loading) return m(LoadingIndicator, {
      display: "block",
      size: "small"
    });
    if (failed) {
      return m("p", {
        className: "helpText"
      }, app.translator.trans('fof-translate.admin.settings.deepl.glossaries_failed'), ' ', m(Button, {
        className: "Button Button--link",
        icon: "fas fa-sync",
        onclick: () => this.load()
      }, app.translator.trans('fof-translate.admin.settings.deepl.glossaries_retry_button')));
    }
    const pairs = Object.keys(loaded ?? {}).sort();
    if (!pairs.length) {
      return m("p", {
        className: "helpText"
      }, app.translator.trans('fof-translate.admin.settings.deepl.glossaries_empty'));
    }
    return pairs.map(pair => {
      const [source, target] = pair.split('_to_');
      return this.attrs.page.buildSettingComponent({
        setting: `fof-translate.deepl.glossary_${pair}`,
        type: 'select',
        label: app.translator.trans('fof-translate.admin.settings.deepl.glossary_pair_label', {
          source: (source ?? pair).toUpperCase(),
          target: (target ?? '').toUpperCase()
        }),
        options: {
          none: app.translator.trans('fof-translate.admin.settings.deepl.glossary_none_option'),
          ...loaded[pair]
        }
      });
    });
  }
}
flarum.reg.add('fof-translate', 'admin/components/DeeplGlossarySettings', DeeplGlossarySettings);