import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import extractText from 'flarum/common/utils/extractText';
/**
 * Terms that are never translated, stored as a JSON array in `fof-translate.glossary`.
 */
export default class GlossaryEditor extends Component {
  draft = '';
  terms() {
    const raw = this.attrs.page.setting('fof-translate.glossary')();
    if (!raw) return [];
    try {
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed.filter(term => typeof term === 'string') : [];
    } catch {
      return [];
    }
  }
  save(terms) {
    this.attrs.page.setting('fof-translate.glossary')(JSON.stringify(terms));
  }
  add() {
    const term = this.draft.trim();
    const terms = this.terms();
    if (term && !terms.includes(term)) {
      this.save([...terms, term]);
    }
    this.draft = '';
  }
  remove(index) {
    const terms = this.terms();
    terms.splice(index, 1);
    this.save(terms);
  }
  view() {
    const terms = this.terms();
    const inputId = 'fof-translate-glossary-input';
    return m("div", {
      className: "Form-group FofTranslateGlossary"
    }, m("label", {
      for: inputId
    }, app.translator.trans('fof-translate.admin.settings.glossary.label')), m("p", {
      className: "helpText"
    }, app.translator.trans('fof-translate.admin.settings.glossary.help')), terms.length ? m("ul", {
      className: "FofTranslateGlossary-terms"
    }, terms.map((term, index) => m("li", {
      className: "FofTranslateGlossary-term",
      key: term
    }, m("span", {
      className: "FofTranslateGlossary-termText"
    }, term), m(Button, {
      className: "Button Button--icon Button--link FofTranslateGlossary-remove",
      icon: "fas fa-times",
      "aria-label": extractText(app.translator.trans('fof-translate.admin.settings.glossary.remove_button', {
        term
      })),
      onclick: () => this.remove(index)
    })))) : m("p", {
      className: "helpText FofTranslateGlossary-empty"
    }, app.translator.trans('fof-translate.admin.settings.glossary.empty_text')), m("div", {
      className: "FofTranslateGlossary-add"
    }, m("input", {
      id: inputId,
      className: "FormControl",
      value: this.draft,
      placeholder: extractText(app.translator.trans('fof-translate.admin.settings.glossary.placeholder')),
      oninput: e => this.draft = e.target.value,
      onkeydown: e => {
        if (e.key === 'Enter') {
          // Enter would submit the settings form.
          e.preventDefault();
          this.add();
        }
      }
    }), m(Button, {
      className: "Button",
      icon: "fas fa-plus",
      disabled: !this.draft.trim(),
      onclick: () => this.add()
    }, app.translator.trans('fof-translate.admin.settings.glossary.add_button'))));
  }
}
flarum.reg.add('fof-translate', 'admin/components/GlossaryEditor', GlossaryEditor);